Here is the commit message:
mm/huge_memory: fix use of NULL folio in
 move_pages_huge_pmd()

move_pages_huge_pmd() handles UFFDIO_MOVE for both normal THPs and huge
zero pages.  For the huge zero page path, src_folio is explicitly set to
NULL, and is used as a sentinel to skip folio operations like lock and
rmap.

In the huge zero page branch, src_folio is NULL, so folio_mk_pmd(NULL,
pgprot) passes NULL through folio_pfn() and page_to_pfn().  With
SPARSEMEM_VMEMMAP this silently produces a bogus PFN, installing a PMD
pointing to non-existent physical memory.  On other memory models it is a
NULL dereference.

Use page_folio(src_page) to obtain the valid huge zero folio from the
page, which was obtained from pmd_page() and remains valid throughout.

After commit d82d09e48219 ("mm/huge_memory: mark PMD mappings of the huge
zero folio special"), moved huge zero PMDs must remain special so
vm_normal_page_pmd() continues to treat them as special mappings.

move_pages_huge_pmd() currently reconstructs the destination PMD in the
huge zero page branch, which drops PMD state such as pmd_special() on
architectures with CONFIG_ARCH_HAS_PTE_SPECIAL.  As a result,
vm_normal_page_pmd() can treat the moved huge zero PMD as a normal page
and corrupt its refcount.

Instead of reconstructing the PMD from the folio, derive the destination
entry from src_pmdval after pmdp_huge_clear_flush(), then handle the PMD
metadata the same way move_huge_pmd() does for moved entries by marking it
soft-dirty and clearing uffd-wp.

Link: https://lkml.kernel.org/r/a1e787dd-b911-474d-8570-f37685357d86@lucifer.local
Fixes: e3981db444a0 ("mm: add folio_mk_pmd()")
Signed-off-by: Chris Down <chris@chrisdown.name>
Signed-off-by: Lorenzo Stoakes <lorenzo.stoakes@oracle.com>
Reviewed-by: Lorenzo Stoakes <lorenzo.stoakes@oracle.com>
Tested-by: Lorenzo Stoakes <lorenzo.stoakes@oracle.com>
Acked-by: David Hildenbrand (Arm) <david@kernel.org>
Cc: <stable@vger.kernel.org>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
In `move_pages_huge_pmd()`, the huge zero page branch sets `src_folio = NULL`, then calls `folio_mk_pmd(NULL, ...)`, which leads to a NULL folio dereference or bogus PFN. Additionally, reconstructing the destination PMD from the folio (instead of deriving from the cleared source PMD value) drops the `pmd_special()` flag on architectures with `CONFIG_ARCH_HAS_PTE_SPECIAL`, causing subsequent `vm_normal_page_pmd()` to incorrectly treat the moved huge zero PMD as a normal page and corrupt its refcount.

Here is the patch:
  */
 int move_pages_huge_pmd(struct mm_struct *mm, pmd_t *dst_pmd, pmd_t *src_pmd, pmd_t dst_pmdval,
 			struct vm_area_struct *dst_vma, struct vm_area_struct *src_vma,
 			unsigned long dst_addr, unsigned long src_addr)
 {
 	pmd_t _dst_pmd, src_pmdval;
 	struct page *src_page;
 	struct folio *src_folio;
 	spinlock_t *src_ptl, *dst_ptl;
 	pgtable_t src_pgtable;
 	struct mmu_notifier_range range;
 	int err = 0;

 	src_pmdval = *src_pmd;
 	src_ptl = pmd_lockptr(mm, src_pmd);

 	lockdep_assert_held(src_ptl);
 	vma_assert_locked(src_vma);
 	vma_assert_locked(dst_vma);

 	/* Sanity checks before the operation */
 	if (WARN_ON_ONCE(!pmd_none(dst_pmdval)) || WARN_ON_ONCE(src_addr & ~HPAGE_PMD_MASK) ||
 	    WARN_ON_ONCE(dst_addr & ~HPAGE_PMD_MASK)) {
 		spin_unlock(src_ptl);
 		return -EINVAL;
 	}

 	if (!pmd_trans_huge(src_pmdval)) {
 		spin_unlock(src_ptl);
 		if (pmd_is_migration_entry(src_pmdval)) {
 			pmd_migration_entry_wait(mm, &src_pmdval);
 			return -EAGAIN;
 		}
 		return -ENOENT;
 	}

 	src_page = pmd_page(src_pmdval);

 	if (!is_huge_zero_pmd(src_pmdval)) {
 		if (unlikely(!PageAnonExclusive(src_page))) {
 			spin_unlock(src_ptl);
 			return -EBUSY;
 		}

 		src_folio = page_folio(src_page);
 		folio_get(src_folio);
 	} else
 		src_folio = NULL;

 	spin_unlock(src_ptl);

 	flush_cache_range(src_vma, src_addr, src_addr + HPAGE_PMD_SIZE);
 	mmu_notifier_range_init(&range, MMU_NOTIFY_CLEAR, 0, mm, src_addr,
 				src_addr + HPAGE_PMD_SIZE);
 	mmu_notifier_invalidate_range_start(&range);

 	if (src_folio)
 		folio_lock(src_folio);

 	dst_ptl = pmd_lockptr(mm, dst_pmd);
 	double_pt_lock(src_ptl, dst_ptl);
 	if (unlikely(!pmd_same(*src_pmd, src_pmdval) ||
 		     !pmd_same(*dst_pmd, dst_pmdval))) {
 		err = -EAGAIN;
 		goto unlock_ptls;
 	}
 	if (src_folio) {
 		if (folio_maybe_dma_pinned(src_folio) ||
 		    !PageAnonExclusive(&src_folio->page)) {
 			err = -EBUSY;
 			goto unlock_ptls;
 		}

 		if (WARN_ON_ONCE(!folio_test_head(src_folio)) ||
 		    WARN_ON_ONCE(!folio_test_anon(src_folio))) {
 			err = -EBUSY;
 			goto unlock_ptls;
 		}

 		src_pmdval = pmdp_huge_clear_flush(src_vma, src_addr, src_pmd);
 		/* Folio got pinned from under us. Put it back and fail the move. */
 		if (folio_maybe_dma_pinned(src_folio)) {
 			set_pmd_at(mm, src_addr, src_pmd, src_pmdval);
 			err = -EBUSY;
 			goto unlock_ptls;
 		}

 		folio_move_anon_rmap(src_folio, dst_vma);
 		src_folio->index = linear_page_index(dst_vma, dst_addr);

 		_dst_pmd = folio_mk_pmd(src_folio, dst_vma->vm_page_prot);
 		/* Follow mremap() behavior and treat the entry dirty after the move */
 		_dst_pmd = pmd_mkwrite(pmd_mkdirty(_dst_pmd), dst_vma);
 	} else {
 		src_pmdval = pmdp_huge_clear_flush(src_vma, src_addr, src_pmd);
-		_dst_pmd = folio_mk_pmd(src_folio, dst_vma->vm_page_prot);
+		_dst_pmd = move_soft_dirty_pmd(src_pmdval);
+		_dst_pmd = clear_uffd_wp_pmd(_dst_pmd);
 	}
 	set_pmd_at(mm, dst_addr, dst_pmd, _dst_pmd);

 	src_pgtable = pgtable_trans_huge_withdraw(mm, src_pmd);
 	pgtable_trans_huge_deposit(mm, dst_pmd, src_pgtable);
 unlock_ptls:
 	double_pt_unlock(src_ptl, dst_ptl);
 	/* unblock rmap walks */
 	if (src_folio)
 		folio_unlock(src_folio);
 	mmu_notifier_invalidate_range_end(&range);
 	if (src_folio)
 		folio_put(src_folio);
 	return err;
 }
 #endif /* CONFIG_USERFAULTFD */


